import { Guid } from "@Obsidian/Types";

/**
 * What the chat shell is told about the person opening it: whether chat may open for them
 * and, when it may, the public half of the church's platform settings. It never carries a
 * token or a key; the shell asks for a token separately, and every ask re-runs the gates.
 */
export type ChatShellSessionBag = {
    /**
     * Gets or sets the outcome of the session gates as a stable snake_case code, "ok" when
     * chat may open. The shell shows a message for every other value.
     */
    gate?: string | null;

    /** Gets or sets the chat platform's address, when the gates passed. */
    projectUrl?: string | null;

    /**
     * Gets or sets the platform's publishable key, which is public by design, when the gates
     * passed.
     */
    publishableKey?: string | null;

    /** Gets or sets the church's identifier on the platform, when the gates passed. */
    tenantId?: Guid | null;

    /**
     * Gets or sets the person's primary alias, which is who the platform knows them as, when
     * the gates passed.
     */
    personAliasGuid?: Guid | null;

    /**
     * Gets or sets whether the person may start a direct message, from the church's Direct
     * Message Access data view, evaluated once when chat opens.
     */
    canStartDm: boolean;
};
